def max_window_sum(xs, k):
    if k <= 0 or len(xs) < k:
        return None

    window = xs[:k]
    best_sum = sum(window)

    for index in range(len(xs) - k, len(xs)):
        window = window[:-1] + xs[index+k:] if len(window) > 0 else []
        current_sum = sum(window)
        if current_sum > best_sum:
            best_sum = current_sum

    return best_sum
