def max_window_sum(xs, k):
    if k < 1 or k > len(xs):
        return None

    # Initialize with the sum of the first k elements
    if len(xs) < k:
        return None

    total = sum(xs[:k])
    best = total

    # Iterate through the rest of the array, updating when a larger sum is found
    for i in range(1, len(xs) - 1):
        total = best + xs[i] - xs[i - k]
        if total > best:
            best = total

    return best
