def merge_intervals(intervals):
    merged = []
    if len(intervals) == 0:
        return merged

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    for i in range(len(sorted_intervals)):
        current = sorted_intervals[i]  # [start, end]

        if len(merged) == 0:
            merged.append(current)
        else:
            last_merged = merged[-1]  # [start, end]

            if current[0] <= last_merged[1]:
                # Overlap or touch, extend the last merged interval
                new_end = max(last_merged[1], current[1])
                merged[-1] = [last_merged[0], new_end]
            else:
                # Disjoint, add a new interval to the end of merged list
                merged.append(current)

    return merged
