def merge_intervals(intervals):
    merged = []
    # Handle empty list explicitly to avoid index error on first iteration
    if not intervals:
        return []

    # Sort intervals by start time
    sorted_intervals = sorted(intervals)

    for i in range(len(sorted_intervals)):
        # Start of the current interval to merge with the last one in merged list
        start = sorted_intervals[i][0]
        end = sorted_intervals[i][1]

        if i == len(sorted_intervals) - 1:
            # Last interval, add it alone or check for overlaps
            if start == merged[-1][0]:
                # Overlap or touch: extend the last interval with current one if necessary
                end = max(end, merged[-1][1])
            else:
                # No overlap from the start of new interval, add it
                merged.append([end, end])
        else:
            # Check if there is overlap or touch with the last interval in merged list
            if start < merged[-1][0]:
                # Current interval and the previous one don't overlap; add a new segment
                merged.append([start, end])
            else:
                # This interval overlaps or touches the last one in merged list; extend it
                end = max(end, merged[-1][1])

    return merged
```

